import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 998244353;
    static final int G = 3;

    static long fastPow(long base, int exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static void fft(long[] array, int length, int dir) {
        int n = length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; j >= bit; bit >>= 1) j -= bit;
            j += bit;
            if (i < j) {
                long temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
        for (int size = 2; size <= n; size <<= 1) {
            long wlen = fastPow(G, (MOD - 1) / size);
            if (dir == -1) wlen = fastPow(wlen, MOD - 2);
            for (int start = 0; start < n; start += size) {
                long w = 1;
                for (int k = start; k < start + size / 2; k++) {
                    long u = array[k];
                    long v = array[k + size / 2] * w % MOD;
                    array[k] = (u + v) % MOD;
                    array[k + size / 2] = (u - v + MOD) % MOD;
                    w = w * wlen % MOD;
                }
            }
        }
        if (dir == -1) {
            long invN = fastPow(n, MOD - 2);
            for (int i = 0; i < n; i++) array[i] = array[i] * invN % MOD;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt(), m = scanner.nextInt();
        int size = 1, halfN = n / 2;
        while (size < (9 * halfN + 1)) size <<= 1;
        long[] A = new long[size];
        long[] B = new long[size];

        A[0] = 1;
        for (int i = 0; i < m; i++) {
            int x = scanner.nextInt();
            B[x] = 1;
        }

        fft(A, size, 1);
        fft(B, size, 1);

        for (int i = 0; i < size; i++) {
            if (A[i] != 0 && B[i] != 0) {
                A[i] = A[i] * fastPow(B[i], halfN) % MOD;
            } else {
                A[i] = 0;
            }
        }

        fft(A, size, -1);

        long total = 0;
        for (int i = 0; i < size; i++) {
            total = (total + A[i] * A[i]) % MOD;
        }
        System.out.println(total);
        scanner.close();
    }
}
